const button=(attrs,text,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
const scene=(s,id)=>s.scenes.find(p=>p.id===id),thread=(s,id)=>s.threads.find(t=>t.id===id),members=(s,p)=>p.threadIds.map(id=>thread(s,id).label).join(' · ');
let visit=null;
export function resetTwoThreads(){visit=null;}
function makeSlot(source,work){const s=clone(source),w=clone(work||newThreadWork(source));return {source:s,work:w,selected:w.order[0],turn:'arrange',folds:{},frame:0,demoSelected:s.teaching[0].order[0],status:''};}
function state(book,owner){if(!visit||visit.book!==book||visit.owner!==owner){visit={book,owner,active:threadCases[0].id,screen:'draft',card:null,drafts:new Map(),copies:new Map(),readonly:new Map(),page:null,boundRoot:null,binding:null};visit.drafts.set(visit.active,makeSlot(makeThreadSource(visit.active)));}return visit;}
const current=v=>v.screen==='draft'?v.drafts.get(v.active):v.screen==='card'?v.readonly.get(v.card):null;
