function orderList(s,order,selected,{scope='current',demo=false,compact=false}={}){const attr=demo?'data-tt-demo-scene':scope==='author'?'data-tt-reference-scene':'data-tt-scene';return `<ol class="tt-order${compact?' tt-order-compact':''}" ${scope==='current'?'data-tt-order':''} data-tt-order-scope="${scope}">${order.map((id,i)=>{const p=scene(s,id);return `<li>${button(`${attr}="${esc(id)}" aria-pressed="${id===selected}"`,`${i+1}. ${p.title}`,id===selected)}${badges(s,p)}</li>`;}).join('')}</ol>`;}
function mapHTML(s,order,scope){return `<div class="tt-map" data-tt-map="${scope}">${threadMap(s,order).map(t=>`<section data-tt-thread="${esc(t.id)}"><h4>${esc(t.label)}</h4><p data-tt-positions="${esc(t.id)}" data-tt-position-values="${t.positions.join(',')}">Appears at positions ${t.positions.join(', ')}.</p>${t.returns.length?`<ol>${t.returns.map(r=>`<li data-tt-return data-tt-from="${r.from}" data-tt-to="${r.to}" data-tt-gap="${r.gap}"><strong>${r.from}. ${esc(r.fromTitle)}</strong> → <strong>${r.to}. ${esc(r.toTitle)}</strong><br>${r.gap} intervening ${r.gap===1?'scene':'scenes'}</li>`).join('')}</ol>`:`<p>${esc(T.noReturn)}</p>`}</section>`).join('')}</div>`;}
function fold(a,id,title,body,attrs=''){return `<details data-tt-fold="${id}" ${attrs}${a.folds[id]?' open':''}><summary>${esc(title)}</summary>${body}</details>`;}
