 const binding={};v.boundRoot=root;v.binding=binding;const a=current(v),source=a?.source,screen=v.screen,active=v.active,card=v.card,route=location.hash,rootChain=[],chains=new WeakMap();
 for(let n=root;n;n=n.parentNode)rootChain.push([n,n.parentNode]);
