 const live=n=>{try{return visit===v&&v.book===book&&v.boundRoot===root&&v.binding===binding&&required.every(k=>ctx[k]===callbacks[k])&&validOwner(owner())&&owner()===v.owner&&ctx.notebook()===book&&ctx.isActive()===true&&ctx.isThreadsActive()===true&&route==='#learn/english'&&location.hash===route&&document.querySelector('[data-tt-root]')===root&&attached(n)&&visible(n)&&!n.disabled&&v.screen===screen&&v.active===active&&v.card===card&&current(v)===a&&a?.source===source&&a?.work===expected&&bytes(source)===sourceBytes&&sourceBytes!==null&&bytes(expected)===workBytes&&workBytes!==null&&own(book,'threadReadings')===rootPresent&&book.threadReadings===rawRoot&&bytes(rawRoot)===rawBytes&&rawBytes!==null&&(screen!=='card'||threadSheetsView(book).items.some(r=>r.readable&&r.id===card&&r.raw===a.raw&&bytes(r.raw)===a.rawBytes));}catch{return false;}};
 const adopt=()=>{expected=a?.work;sourceBytes=bytes(source);workBytes=bytes(expected);rawRoot=book.threadReadings;rawBytes=bytes(rawRoot);rootPresent=own(book,'threadReadings');};
 const guard=n=>{chains.set(n,chain(n));for(const type of ['click','input','change','toggle','keydown','focusin'])n.addEventListener(type,e=>{if(!live(n)){e.preventDefault();e.stopImmediatePropagation();}},{capture:true});};
