 const redraw=(selector='#tt-title')=>{ctx.render?.();const r=document.querySelector('[data-tt-root]'),candidate=r?.querySelector(selector),n=candidate&&!candidate.disabled&&visible(candidate)?candidate:r?.querySelector('#tt-title,#tt-heading');n?.focus({preventScroll:true});if(n){const b=n.getBoundingClientRect();if(b.top<0||b.bottom>innerHeight)n.scrollIntoView({block:'nearest'});}};
