 function update(action,value){if(screen!=='draft'||!a)return false;const next=changeThreadWork(source,a.work,action,value);if(!next)return false;a.work=next;adopt();return true;}
 function on(selector,fn,target='#tt-title'){root.querySelectorAll(selector).forEach(n=>n.addEventListener('click',()=>{if(!live(n))return;folds();message('');stop();if(fn(n)!==false)redraw(typeof target==='function'?target(n):target);}));}
