 on('[data-tt-case]',n=>{const id=n.dataset.ttCase;if(!threadCases.some(c=>c.id===id))return false;if(!v.drafts.has(id))v.drafts.set(id,makeSlot(makeThreadSource(id)));v.active=id;v.screen='draft';v.card=null;});
 on('[data-tt-card]',n=>{const id=n.dataset.ttCard;if(!threadSheetsView(book).items.some(r=>r.readable&&r.id===id))return false;v.card=id;v.screen='card';});
 on('[data-tt-page]',n=>{v.page+=Number(n.dataset.ttPage);},n=>{const d=Number(n.dataset.ttPage),last=Math.max(0,Math.ceil(threadSheetsView(book).items.length/8)-1);return attr('page',d<0?(v.page>0?-1:1):(v.page<last?1:-1));});
 on('[data-tt-turn]',n=>{if(!a||!['arrange','read'].includes(n.dataset.ttTurn))return false;a.turn=n.dataset.ttTurn;},'#tt-turn-title');
